"use client";

import Engine from "./feature-dialog-engine.jsx";
import css from "./feature-dialog-styles";

export interface FeatureDialogImage {
  src: string;
  alt: string;
}
export interface FeatureDialogProps {
  className?: string;
  duration?: number;
  ease?: string;
  disable?: string;
  label?: string;
  title?: string;
  tileImage?: FeatureDialogImage;
  sheetTitle?: string;
  sheetText?: string;
  actionLabel?: string;
  onAction?: () => void;
  onOpenChange?: (open: boolean) => void;
  listItems?: string[];
  mediaImages?: FeatureDialogImage[];
  stats?: { num: string; label: string }[];
  sheetImage?: FeatureDialogImage;
  outro?: string;
}

export function FeatureDialog(props: FeatureDialogProps) {
  return (
    <>
      <style>{css}</style>
      <Engine {...props} />
    </>
  );
}

import type { FeatureDialogProps } from "./feature-dialog";
import type { ComponentType } from "react";
declare const Engine: ComponentType<FeatureDialogProps>;
export default Engine;
